def min_time_to_reach_n(n, m, railways):
    # Create adjacency lists for railways and roads
    rail_adj = [[] for _ in range(n + 1)]
    road_adj = [[] for _ in range(n + 1)]

    for u, v in railways:
        rail_adj[u].append(v)
        rail_adj[v].append(u)
        road_adj[u].append(v)
        road_adj[v].append(u)

    # BFS to find the shortest path for the bus (road network)
    def bfs_bus(start):
        queue = deque([(start, 0)])
        visited = [False] * (n + 1)
        visited[start] = True

        while queue:
            current, time = queue.popleft()
            if current == n:
                return time

            for neighbor in road_adj[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append((neighbor, time + 1))

        return float('inf')

    # BFS to find the shortest path for the train (railway network)
