        queue = deque([(start, 0)])
        visited = [False] * (n + 1)
        visited[start] = True

        while queue:
            current, time = queue.popleft()
            if current == n:
                return time

            for neighbor in rail_adj[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append((neighbor, time + 1))

        return float('inf')

    # Find the minimum time for the bus to reach town n
    bus_time = bfs_bus(1)

    # Find the minimum time for the train to reach town n
    train_time = bfs_train(1)

    # Check if both vehicles can reach town n without overlapping
    if bus_time < float('inf') and train_time < float('inf'):
