from collections import defaultdict, deque

def min_time_to_reach_n(n, m, railways):
    graph = defaultdict(list)
    for u, v in railways:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start, end):
        queue = deque([(start, 0)])
        visited = set([start])
        while queue:
            current, time = queue.popleft()
            if current == end:
                return time
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, time + 1))
        return float('inf')

    def dfs(current, train_pos, time, visited):
        if current == n:
            return time
        max_time = float('-inf')
        for neighbor in graph[current]:
            if neighbor != train_pos and neighbor not in visited:
                visited.add(neighbor)
                max_time = max(max_time, dfs(neighbor, train_pos, time + 1, visited))
                visited.remove(neighbor)
        return max_time

    min_time = float('inf')
    for i in range(1, n + 1):
        if i != 1 and i != n:
            train_time = bfs(1, i)
            if train_time < float('inf'):
                bus_visited = {i}
                bus_time = dfs(i, i, 0, bus_visited)
                min_time = min(min_time, max(train_time, bus_time))

    return min_time if min_time != float('inf') else -1

